import json
nb = json.load(open("inputs/20260821_ana.ipynb"))
for i,c in enumerate(nb["cells"]):
    for o in c.get("outputs",[]) or []:
        d = o.get("data") or {}
        for k in d:
            if not k.startswith("text/plain"):
                print(i, o.get("output_type"), k)
    if c.get("attachments"): print(i, "ATTACHMENTS", list(c["attachments"]))
EOF

